int main() {
    // 记录每一层出现指定关键字的数量
    vector<map<string,int>> cnts(11);
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) {
        string url;
        cin >> url;
        // 按照这个规律进行切割之后 索引为0的位置为空字符串
        vector<string> parts = split(url, "/");
        for (int j = 1; j < parts.size(); j++) {
            cnts[j][parts[j]] += 1;
        }
    }
​
