public class Main {
    // 找到左边小于本身高度的最近点
    static int[] findLeftSmall(int[] nums) {
        int n = nums.length;
        int[] left = new int[n];
        Arrays.fill(left, -1);
        // 单调栈 维持一个单调递增
        Stack<Integer> stack = new Stack<>();
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) {
                stack.pop();
            }
            if (!stack.isEmpty()) {
                left[i] = stack.peek();
            }
            stack.push(i);
        }
        return left;
    }
​
    // 找到右边小于本身高度的最近点
    static int[] findRightSmaller(int[] nums) {
        int n = nums.length;
        int[] right = new int[n];
        Arrays.fill(right, -1);
        // 单调栈 维持单调递增
        Stack<Integer> stack = new Stack<>();
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) {
                stack.pop();
            }
            if (!stack.isEmpty()) {
                right[i] = stack.peek();
            }
            stack.push(i);
        }
        return right;
    }
​
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        String[] parts = line.trim().split(" ");
        int n = parts.length;
        int[] heights = new int[n];
        for (int i = 0; i < n; i++) {
            heights[i] = Integer.parseInt(parts[i]);
        }
​
        // 数量小于三肯定不存在指定元组
        if (n < 3) {
            System.out.println(-1);
            return;
        }
​
        int[] left = findLeftSmall(heights);
        int[] right = findRightSmaller(heights);
​
        int res = Integer.MAX_VALUE;
        for (int j = 0; j < n; j++) {
            // 左侧小于自己最近的点
            int i = left[j];
            int k = right[j];
            // 左侧或右侧不存在这样的点
            if (i == -1 || k == -1) continue;
            res = Math.min(res, k - i);
        }
​
        // 输出结果
        if (res == Integer.MAX_VALUE) {
            System.out.println(-1);
        } else {
            System.out.println(res);
        }
    }
}
