const readline = require("readline");
​
function findLeftSmall(nums) {
  let n = nums.length;
  let left = new Array(n).fill(-1);
  // 单调栈 维持一个单调递增
  let stack = [];
  for (let i = 0; i < n; i++) {
    while (stack.length && nums[stack[stack.length - 1]] >= nums[i]) {
      stack.pop();
    }
    if (stack.length) {
      left[i] = stack[stack.length - 1];
    }
    stack.push(i);
  }
  return left;
}
​
function findRightSmaller(nums) {
  let n = nums.length;
  let right = new Array(n).fill(-1);
  // 单调栈 维持单调递增
  let stack = [];
  for (let i = n - 1; i >= 0; i--) {
    while (stack.length && nums[stack[stack.length - 1]] >= nums[i]) {
      stack.pop();
    }
    if (stack.length) {
      right[i] = stack[stack.length - 1];
    }
    stack.push(i);
  }
  return right;
}
