package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strings"
    "strconv"
)
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    writer := bufio.NewWriter(os.Stdout)
    defer writer.Flush()
​
    // 读取第一行，表示有多少个 url
    var n int
    fmt.Fscanln(reader, &n)
​
    // cnts[i] 表示第 i 层的关键词出现次数
    cnts := make([]map[string]int, 11)
    for i := range cnts {
        cnts[i] = make(map[string]int)
    }
​
    // 逐行读取 url 并统计每一层的关键词
    for i := 0; i < n; i++ {
        line, _ := reader.ReadString('\n')
        url := strings.TrimSpace(line)
        parts := strings.Split(url, "/")
        for j := 1; j < len(parts); j++ {
            cnts[j][parts[j]]++
        }
    }
​
    // 读取最后一行：格式为 L key
    lastLine, _ := reader.ReadString('\n')
    tokens := strings.Fields(lastLine)
    L, _ := strconv.Atoi(tokens[0])
    key := tokens[1]
​
    fmt.Fprintln(writer, cnts[L][key])
}
